Systems.Set.quaternary_two_triadic.{u_1, u_2, u_3, u_4} {A : Type u_1} {B : Type u_2} {C : Type u_3}
  {D : Type u_4} (S : Set (A × B × C × D)) :
  ∃ T₁ T₂, ∀ (p : A × B × C × D), p ∈ S ↔ ∃ z, (p.1, p.2.1, z) ∈ T₁ ∧ (z, p.2.2.1, p.2.2.2) ∈ T₂

